		matchCount := 0

		for _, c := range rule.Constraints {
			if err := validate(c); err != nil {
				return resp, err
			}
			c.Operator = strings.ToLower(strings.TrimSpace(c.Operator))

			v := r.Context[c.Property]

			var (
				match bool
				err   error
			)

			switch c.Type {
			case flipt.ComparisonType_STRING_COMPARISON_TYPE:
				if _, ok := stringOperators[c.Operator]; !ok {
					return resp, ErrInvalidf("constraint operator %q is not valid for type string", c.Operator)
				}
				match = matchesString(c, v)
			case flipt.ComparisonType_NUMBER_COMPARISON_TYPE:
				if _, ok := numberOperators[c.Operator]; !ok {
					return resp, ErrInvalidf("constraint operator %q is not valid for type number", c.Operator)
				}
				match, err = matchesNumber(c, v)
			case flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE:
				if _, ok := booleanOperators[c.Operator]; !ok {
					return resp, ErrInvalidf("constraint operator %q is not valid for type boolean", c.Operator)
				}
				match, err = matchesBool(c, v)
			default:
				return resp, ErrInvalid("unknown constraint type")
			}

			if err != nil {
				return resp, err
			}

